class _DashboardState extends State<Dashboard>{Map<String,dynamic>? price;List<dynamic> markets=[];Future<void> load()async{final p=jsonDecode(await rootBundle.loadString('assets/data/pig-price.json')) as Map<String,dynamic>;final m=jsonDecode(await rootBundle.loadString('assets/data/platform.json')) as Map<String,dynamic>;if(mounted)setState((){price=p;markets=m['markets'] as List;});}@override void initState(){super.initState();load();}@override Widget build(BuildContext context){final p=price;return Scaffold(appBar:AppBar(title:Row(children:[Image.asset('assets/images/dondonhae_symbol.png',width:34,height:34),const SizedBox(width:9),const Text('돈돈해',style:TextStyle(fontWeight:FontWeight.w900))])),body:p==null?const Center(child:CircularProgressIndicator()):RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.all(16),children:[const Text('양돈의 오늘을 든든하게',style:TextStyle(fontSize:18,fontWeight:FontWeight.w800)),const SizedBox(height:14),Card(child:ListTile(title:const Text('전국 돈가',style:TextStyle(fontWeight:FontWeight.w800)),subtitle:Text('${p!['price']} 원/kg · 전일 대비 ${p['change']}원'),trailing:const Icon(Icons.chevron_right))),const SizedBox(height:18),const Text('국제정세 & 원료 동향',style:TextStyle(fontSize:19,fontWeight:FontWeight.w900)),const SizedBox(height:10),GridView.builder(shrinkWrap:true,physics:const NeverScrollableScrollPhysics(),itemCount:markets.length,gridDelegate:const SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount:2,crossAxisSpacing:10,mainAxisSpacing:10),itemBuilder:(c,i){final e=markets[i] as Map<String,dynamic>;return Card(child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('${e['label']??e['name']}',style:const TextStyle(fontWeight:FontWeight.w800)),const Spacer(),Text('${e['value']??'-'}',style:const TextStyle(fontSize:23,fontWeight:FontWeight.w900)),Text('${e['unit']??''}',style:const TextStyle(fontSize:11))])));}),const SizedBox(height:14),Card(child:ListTile(leading:const Icon(Icons.coronavirus_outlined),title:const Text('질병 정보',style:TextStyle(fontWeight:FontWeight.w800)),subtitle:const Text('국내·해외 가축질병 발생 현황'),trailing:const Icon(Icons.chevron_right),onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>const DiseasePage())))),const SizedBox(height:10),const Card(child:ListTile(leading:Icon(Icons.cloud_outlined),title:Text('날씨와 농장 대응',style:TextStyle(fontWeight:FontWeight.w800)),subtitle:Text('GPS 기반 기상·농장 환경 정보')))])));}}
